ltest=[{"n":i+1,"question_zh":"（听录音，对的选✓，错的选✗）"+p,"options":["✓","✗"],"script_zh":s,"answer":a,"explanation_mn":e} for i,(p,s,a,e) in enumerate(JT)]

def _mk(n,q,opts,ans,expl,seed,extra=None):
    o,_=shuffle(opts,ans,seed); d={"n":n,"question_zh":q,"options":o,"answer":ans,"explanation_mn":expl}
    if extra: d.update(extra)
    return d
def RD(n,q,qmn,opts,ans,expl,seed): return _mk(n,q,opts,ans,expl,seed,{"question_mn":qmn})
def SO(n,words,ans,dis,expl,seed): return _mk(n,"（把词连成句子）"+words,[ans]+dis,ans,expl,seed)
def CS(n,q,ans,expl,seed): return _mk(n,q,["又","再"],ans,expl,seed)
def SI(n,q,ans,expl,seed): return _mk(n,q,["1","2","3","4"],ans,expl,seed)
def XZ(n,q,ans,dis,expl,seed): return _mk(n,q,[ans]+dis,ans,expl,seed)

